// =====================================================================================
// SECTION 0 — RNG, math helpers, small matrix algebra
// =====================================================================================

function mulberry32(seed){
  let a = seed >>> 0;
  return function(){
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

class SeededRng {
  constructor(seed){ this.seed = seed >>> 0; this.rand = mulberry32(this.seed); this._spare = null; }
  uniform(){ return this.rand(); }
  range(lo, hi){ return lo + (hi - lo) * this.rand(); }
  gaussian(mean = 0, std = 1){
    if (this._spare !== null){ const v = this._spare; this._spare = null; return mean + std * v; }
    let u, v, s;
    do { u = this.rand() * 2 - 1; v = this.rand() * 2 - 1; s = u * u + v * v; } while (s <= 0 || s >= 1);
    const mul = Math.sqrt(-2 * Math.log(s) / s);
    this._spare = v * mul;
    return mean + std * (u * mul);
  }
  unitVector3(){
    const z = this.range(-1, 1);
    const t = this.range(0, Math.PI * 2);
    const r = Math.sqrt(Math.max(0, 1 - z * z));
    return new THREE.Vector3(r * Math.cos(t), r * Math.sin(t), z);
  }
}

const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
const lerp = (a, b, t) => a + (b - a) * t;
const deg2rad = (d) => d * Math.PI / 180;
const rad2deg = (r) => r * 180 / Math.PI;
const isFiniteVec3 = (v) => Number.isFinite(v.x) && Number.isFinite(v.y) && Number.isFinite(v.z);
const isFiniteQuat = (q) => Number.isFinite(q.x) && Number.isFinite(q.y) && Number.isFinite(q.z) && Number.isFinite(q.w);

// ---- small dense matrix helpers (row-major arrays of arrays), used by the KF ----
const Mat = {
  zeros(r, c){ const m = new Array(r); for (let i = 0; i < r; i++) m[i] = new Array(c).fill(0); return m; },
  identity(n){ const m = Mat.zeros(n, n); for (let i = 0; i < n; i++) m[i][i] = 1; return m; },
  clone(A){ return A.map(row => row.slice()); },
  transpose(A){ const r = A.length, c = A[0].length; const T = Mat.zeros(c, r); for (let i = 0; i < r; i++) for (let j = 0; j < c; j++) T[j][i] = A[i][j]; return T; },
  mul(A, B){
    const r = A.length, k = B.length, c = B[0].length;
    const C = Mat.zeros(r, c);
    for (let i = 0; i < r; i++) for (let j = 0; j < c; j++){ let s = 0; for (let p = 0; p < k; p++) s += A[i][p] * B[p][j]; C[i][j] = s; }
    return C;
  },
  add(A, B){ return A.map((row, i) => row.map((v, j) => v + B[i][j])); },
  sub(A, B){ return A.map((row, i) => row.map((v, j) => v - B[i][j])); },
  scale(A, s){ return A.map(row => row.map(v => v * s)); },
  mulVec(A, v){ return A.map(row => row.reduce((s, a, j) => s + a * v[j], 0)); },
  // Gauss-Jordan inverse for small square matrices (n <= ~8)
  invert(A){
    const n = A.length;
    const M = A.map((row, i) => row.concat(Mat.identity(n)[i]));
    for (let col = 0; col < n; col++){
      let pivot = col;
      for (let r = col + 1; r < n; r++) if (Math.abs(M[r][col]) > Math.abs(M[pivot][col])) pivot = r;
      if (Math.abs(M[pivot][col]) < 1e-12) { M[pivot][col] += 1e-9; }
      [M[col], M[pivot]] = [M[pivot], M[col]];
      const pv = M[col][col];
      for (let j = 0; j < 2 * n; j++) M[col][j] /= pv;
      for (let r = 0; r < n; r++){
        if (r === col) continue;
        const f = M[r][col];
        if (f === 0) continue;
        for (let j = 0; j < 2 * n; j++) M[r][j] -= f * M[col][j];
      }
    }
    return M.map(row => row.slice(n));
  }
};

// Jacobi eigen-decomposition for a symmetric 3x3 matrix -> {values:[3], vectors: THREE.Matrix3 columns}
function eigenSym3(Ain){
  const A = [Ain[0].slice(), Ain[1].slice(), Ain[2].slice()];
  let V = [[1,0,0],[0,1,0],[0,0,1]];
  for (let sweep = 0; sweep < 40; sweep++){
    let off = Math.abs(A[0][1]) + Math.abs(A[0][2]) + Math.abs(A[1][2]);
    if (off < 1e-12) break;
    for (const [p, q] of [[0,1],[0,2],[1,2]]){
      if (Math.abs(A[p][q]) < 1e-14) continue;
      const theta = (A[q][q] - A[p][p]) / (2 * A[p][q]);
      const t = Math.sign(theta || 1) / (Math.abs(theta) + Math.sqrt(theta * theta + 1));
      const c = 1 / Math.sqrt(t * t + 1), s = t * c;
      const app = A[p][p], aqq = A[q][q], apq = A[p][q];
      A[p][p] = c * c * app - 2 * s * c * apq + s * s * aqq;
      A[q][q] = s * s * app + 2 * s * c * apq + c * c * aqq;
      A[p][q] = A[q][p] = 0;
      for (let i = 0; i < 3; i++){
        if (i !== p && i !== q){
          const aip = A[i][p], aiq = A[i][q];
          A[i][p] = A[p][i] = c * aip - s * aiq;
          A[i][q] = A[q][i] = s * aip + c * aiq;
        }
      }
      for (let i = 0; i < 3; i++){
        const vip = V[i][p], viq = V[i][q];
        V[i][p] = c * vip - s * viq;
        V[i][q] = s * vip + c * viq;
      }
    }
  }
  return { values: [A[0][0], A[1][1], A[2][2]], vectors: V };
}

