// Clohessy-Wiltshire / Hill linearized relative motion. Frame: x = radial (outward),
// y = along-track, z = cross-track (orbit-normal). n = target orbit mean motion.
function cwAccel(pos, vel, controlAccel){
  const n = MEAN_MOTION;
  return new THREE.Vector3(
    3 * n * n * pos.x + 2 * n * vel.y + controlAccel.x,
    -2 * n * vel.x + controlAccel.y,
    -n * n * pos.z + controlAccel.z
  );
}

function integrateRelativeMotionRK4(pos, vel, controlAccel, dt){
  const deriv = (p, v) => ({ dp: v.clone(), dv: cwAccel(p, v, controlAccel) });
  const k1 = deriv(pos, vel);
  const p2 = pos.clone().addScaledVector(k1.dp, dt / 2), v2 = vel.clone().addScaledVector(k1.dv, dt / 2);
  const k2 = deriv(p2, v2);
  const p3 = pos.clone().addScaledVector(k2.dp, dt / 2), v3 = vel.clone().addScaledVector(k2.dv, dt / 2);
  const k3 = deriv(p3, v3);
  const p4 = pos.clone().addScaledVector(k3.dp, dt), v4 = vel.clone().addScaledVector(k3.dv, dt);
  const k4 = deriv(p4, v4);
  const newPos = pos.clone().addScaledVector(k1.dp, dt / 6).addScaledVector(k2.dp, dt / 3).addScaledVector(k3.dp, dt / 3).addScaledVector(k4.dp, dt / 6);
  const newVel = vel.clone().addScaledVector(k1.dv, dt / 6).addScaledVector(k2.dv, dt / 3).addScaledVector(k3.dv, dt / 3).addScaledVector(k4.dv, dt / 6);
  return { pos: newPos, vel: newVel };
}

// Body-frame angular-velocity quaternion kinematics: qdot = 0.5 * q (x) [w,0]
function quatDerivBody(q, w){
  const omega = new THREE.Quaternion(w.x, w.y, w.z, 0);
  const dq = q.clone().multiply(omega);
  return new THREE.Quaternion(dq.x * 0.5, dq.y * 0.5, dq.z * 0.5, dq.w * 0.5);
}

// Torque-free / torqued rigid body (Euler's equations) + quaternion kinematics, RK4.
function integrateAttitudeRK4(q, w, inertia, torqueBody, dt){
  const deriv = (qq, ww) => {
    const dq = quatDerivBody(qq, ww);
    const Iw = new THREE.Vector3(inertia.x * ww.x, inertia.y * ww.y, inertia.z * ww.z);
    const wCrossIw = new THREE.Vector3().crossVectors(ww, Iw);
    const dw = new THREE.Vector3(
      (torqueBody.x - wCrossIw.x) / inertia.x,
      (torqueBody.y - wCrossIw.y) / inertia.y,
      (torqueBody.z - wCrossIw.z) / inertia.z
    );
