    this.actuators.commandedTorqueBody.copy(desiredTorqueBody);
    this.actuators.achievedForceBody.copy(achievedForce);
    this.actuators.achievedTorqueBody.copy(achievedTorque);
    return { achievedForce, achievedTorque };
  }

