    const desired6 = [desiredForceBody.x, desiredForceBody.y, desiredForceBody.z, desiredTorqueBody.x, desiredTorqueBody.y, desiredTorqueBody.z];
    const rawDuty = Mat.mulVec(this.pinvMatrix, desired6);
    const starved = this.truth.propellantKg <= 0;
    const achievedForce = new THREE.Vector3();
    const achievedTorque = new THREE.Vector3();
    let impulseUsed = 0;
    this.thrusters.forEach((th, idx) => {
      const cmdDuty = clamp(rawDuty[idx], 0, 1);
      th.commandedDuty = cmdDuty;
      const achDuty = (th.faulted || starved) ? 0 : cmdDuty;
      th.achievedDuty = achDuty;
      if (cmdDuty > 0.05) th.lastFireT = this.t;
      if (achDuty > 0.001){
        th.firedTime += dt * achDuty;
        const F = achDuty * th.maxForce;
