    const mass = CHASER_DRY_MASS_KG + this.truth.propellantKg;
    const accelBody = achievedForceBody.clone().multiplyScalar(1 / mass);
    const accelLVLH = accelBody.clone().applyQuaternion(this.truth.chaser.q);
    const rk = integrateRelativeMotionRK4(this.truth.rel.pos, this.truth.rel.vel, accelLVLH, dt);
