    this.truth.chaser.q = chaserAtt.q; this.truth.chaser.w = chaserAtt.w;

    const targetAtt = integrateAttitudeRK4(this.truth.target.q, this.truth.target.w, TARGET_INERTIA, new THREE.Vector3(), dt);
    this.truth.target.q = targetAtt.q; this.truth.target.w = targetAtt.w;
