    const Ht = Mat.transpose(H);
    const PHt = Mat.mul(P, Ht);
    const S = Mat.add(Mat.mul(H, PHt), R);
    const K = Mat.mul(PHt, Mat.invert(S));
    const dx = Mat.mulVec(K, y);
    const xNew = x.map((xi, i) => xi + dx[i]);
    this.estimate.rel.pos.set(xNew[0], xNew[1], xNew[2]);
    this.estimate.rel.vel.set(xNew[3], xNew[4], xNew[5]);
