    const Pnew = Mat.mul(ImKH, P);
    for (let i = 0; i < 6; i++) for (let j = i + 1; j < 6; j++){ const avg = (Pnew[i][j] + Pnew[j][i]) / 2; Pnew[i][j] = avg; Pnew[j][i] = avg; }
