    const t1 = new THREE.Vector3().crossVectors(u, ref).normalize();
    const t2 = new THREE.Vector3().crossVectors(u, t1).normalize();
    const tangSigma2 = angleSigma2 * estRange * estRange;
    const radialSigma2 = 1e8;
    const B = [[u.x, t1.x, t2.x], [u.y, t1.y, t2.y], [u.z, t1.z, t2.z]];
