  }
  truthClosingRate(){
    const range = Math.max(1e-6, this.truth.rel.pos.length());
    const u = this.truth.rel.pos.clone().divideScalar(range);
    return -u.dot(this.truth.rel.vel);
  }

  // =====================================================================================
