  // =====================================================================================
  setLidarDropout(v){
    v = !!v;
    if (v === this.faults.lidarDropout) return;
    this.faults.lidarDropout = v;
    this._pushLog(v ? 'caution' : 'info', v ? 'Lidar dropout injected — range and range-rate sensing lost.' : 'Lidar restored — range and range-rate sensing nominal.');
  }
  setOpticalDropout(v){
    v = !!v;
    if (v === this.faults.opticalDropout) return;
    this.faults.opticalDropout = v;
    this._pushLog(v ? 'caution' : 'info', v ? 'Optical navigation dropout injected — bearing and target-attitude tracking lost.' : 'Optical navigation restored — bearing and target-attitude tracking nominal.');
  }
  setTargetTumbleInjected(v){
    v = !!v;
    if (!this._nominalTargetW) this._nominalTargetW = this.truth.target.w.clone();
    if (v){
      if (this.truth.target.w.length() < 1e-5){ this.truth.target.w.copy(this._nominalTargetW.length() > 1e-4 ? this._nominalTargetW : this.rng.unitVector3().multiplyScalar(deg2rad(1.6))); }
      this._pushLog('caution', 'Target tumble injected.');
    } else {
      this.truth.target.w.set(0, 0, 0);
      this._pushLog('info', 'Target tumble cleared — target attitude held static.');
    }
  }
  injectStuckThruster(id){
    if (id === undefined || id === null){
      id = this.thrusters.findIndex(t => !t.faulted);
      if (id < 0) id = 0;
    }
    this.setThrusterFault(id);
    this.faults.stuckThrusterActive = true;
    this._pushLog('warning', `Stuck-thruster fault injected on ${this.thrusters[id].label} — commanded firings produce no achieved force.`);
  }
  clearStuckThruster(){
    if (this.stuckThrusterId === null) return;
    this.setThrusterFault(null);
    this.faults.stuckThrusterActive = false;
    this.faults.faultSuspectId = null;
    this.faults.faultConfirmedId = null;
    this._pushLog('info', 'Stuck-thruster fault cleared — full RCS authority restored.');
  }
  // ===== CLASS_BODY_CONTINUES_BELOW =====
}

